<script setup>
import CampusLayout from '../../Layouts/MarketplaceLayout.vue';
import { Link, router } from '@inertiajs/vue3';
import { computed, reactive, ref } from 'vue';
const props = defineProps({ businesses:Array, stats:Object, topProducts:Array, filters:Object });
const form = reactive({ ...(props.filters || {}) });
const loading = ref(false);
const query = () => Object.fromEntries(Object.entries(form).filter(([, v]) => v));
const csvUrl = computed(() => '/tienda/vendedor/reporte.csv?' + new URLSearchParams(query()).toString());
const states = { pending_inventory: 'Reservando inventario', awaiting_payment: 'Esperando pago', confirmed: 'Confirmado', preparing: 'En preparación', ready: 'Listo', delivered: 'Entregado', cancelled: 'Cancelado', expired: 'Expirado', stock_unavailable: 'Sin existencias', return_approved: 'Devolución aprobada' };
function apply() { loading.value = true; router.get('/tienda/vendedor', query(), { preserveState: true, preserveScroll: true, onFinish: () => { loading.value = false; } }); }
</script>
<template><CampusLayout title="Panel vendedor"><div class="max-w-[1180px] mx-auto space-y-5"><div class="flex justify-between items-end"><div><p class="text-xs text-campus-blue font-semibold">3.9 · PANEL DEL VENDEDOR</p><h1 class="text-2xl font-bold text-slate-800">Resumen comercial</h1><p class="text-sm text-slate-500">Solo pedidos de negocios que administras.</p></div><Link href="/tienda/vendedor/pedidos" class="rounded-lg bg-campus-blue text-white px-4 py-2 text-sm">Atender pedidos</Link></div><form class="grid gap-3 rounded-xl border border-campus-border bg-white p-4 sm:grid-cols-4" aria-label="Filtros del reporte de ventas" @submit.prevent="apply"><label class="text-sm font-semibold" for="sd-desde">Desde<input id="sd-desde" v-model="form.desde" type="date" required class="mt-1 block w-full rounded border-slate-300" /></label><label class="text-sm font-semibold" for="sd-hasta">Hasta<input id="sd-hasta" v-model="form.hasta" type="date" required class="mt-1 block w-full rounded border-slate-300" /></label><label class="text-sm font-semibold" for="sd-estado">Estado del pedido<select id="sd-estado" v-model="form.estado" class="mt-1 block w-full rounded border-slate-300"><option value="">Todos</option><option v-for="(label, key) in states" :key="key" :value="key">{{ label }}</option></select></label><div class="flex items-end gap-2"><button class="rounded-lg bg-campus-blue px-4 py-2 text-sm font-semibold text-white disabled:opacity-60" :disabled="loading">{{ loading ? 'Consultando…' : 'Consultar' }}</button><a :href="csvUrl" class="rounded-lg border border-campus-blue px-4 py-2 text-sm font-semibold text-campus-blue">Exportar CSV</a></div></form><p class="text-sm text-slate-500" role="status">Periodo {{ filters?.desde }} a {{ filters?.hasta }}<template v-if="filters?.estado"> · {{ states[filters.estado] }}</template></p><div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-3"><div v-for="item in [{label:'Pedidos',value:stats.orders},{label:'Ventas pagadas',value:'$'+Number(stats.paid_sales).toFixed(2)},{label:'Pendientes',value:stats.pending},{label:'Cancelaciones',value:stats.cancelled}]" :key="item.label" class="bg-white rounded-xl border border-campus-border p-5"><p class="text-xs text-slate-500">{{ item.label }}</p><p class="text-2xl font-bold text-campus-navy mt-2">{{ item.value }}</p></div></div><div class="grid md:grid-cols-2 gap-4"><section class="bg-white border rounded-xl p-5"><h2 class="font-bold mb-3">Tus negocios</h2><p v-for="b in businesses" :key="b.id" class="py-2 border-b text-sm">{{ b.name }} <span class="text-xs text-slate-400">· {{ b.status }}</span></p><p v-if="!businesses.length" class="text-sm text-slate-400">No tienes negocios asignados.</p></section><section class="bg-white border rounded-xl p-5"><h2 class="font-bold mb-3">Productos más vendidos</h2><p v-for="p in topProducts" :key="p.name" class="py-2 border-b text-sm flex justify-between"><span>{{ p.name }}</span><b>{{ p.units }} unidades</b></p><p v-if="!topProducts.length" class="text-sm text-slate-400">Todavía no hay ventas registradas.</p></section></div></div></CampusLayout></template>
